fn limits_valid(limits: &Limits) -> bool {
    limits.bytes_parameter_value <= CEILINGS.bytes_parameter_value && limits.spec_words <= CEILINGS.spec_words && limits.spec_parameters <= CEILINGS.spec_parameters && limits.spec_inputs <= CEILINGS.spec_inputs && limits.part_segment_bytes <= CEILINGS.part_segment_bytes && limits.part_path_segments <= CEILINGS.part_path_segments && limits.field_rule_name <= CEILINGS.field_rule_name && limits.verdict_fields <= CEILINGS.verdict_fields && limits.approval_state <= CEILINGS.approval_state && limits.choices_choices <= CEILINGS.choices_choices && limits.authority_segment_bytes <= CEILINGS.authority_segment_bytes && limits.pattern_segments <= CEILINGS.pattern_segments && limits.delegation_kinds <= CEILINGS.delegation_kinds && limits.authority_grants <= CEILINGS.authority_grants && limits.authority_note_resources <= CEILINGS.authority_note_resources && limits.segment_bytes <= CEILINGS.segment_bytes && limits.name_path <= CEILINGS.name_path
}

