    #[test]
    fn record_number_smallest() {
        let value = Number::new(&CEILINGS, NumberParts { value: 0_u64 }).expect("golden within ceilings");
        let golden: &[u8] = &[0, 0, 0, 0, 0, 0, 0, 0];
        let mut writer = skein_lib::Writer::new(usize::try_from(value.measure()).expect("size fits usize"));
        value.encode(&mut writer).expect("measured room");
        assert_eq!(writer.finish().as_ref(), golden);
        assert_eq!(Number::decode(&CEILINGS, &mut skein_lib::Reader::new(golden)), Ok(value));
    }

